/**
 * DEMO ASSET CATALOG
 * ------------------------------------------------------------------
 * Company names and tickers are used for identification only. Every price,
 * chart, volume and statistic in ELDAR INVEST is generated by a local
 * simulation (see src/lib/market.ts). None of it is real market data.
 * `refPrice` is only a rough anchor for the simulator.
 */

export type AssetType = 'stock' | 'etf';

export type Category =
  | 'Technology'
  | 'Communication'
  | 'Consumer'
  | 'Healthcare'
  | 'Financials'
  | 'Energy'
  | 'Industrials'
  | 'ETFs';

export interface Asset {
  symbol: string;
  name: string;
  type: AssetType;
  category: Category;
  /** Approximate anchor price for the simulator (not a quote). */
  refPrice: number;
  /** Annualised volatility used by the simulator. */
  vol: number;
  /** Annualised drift used by the simulator. */
  drift: number;
  /** Hue (0-360) for the monogram icon. */
  hue: number;
  description: string;
}

