const BY_SYMBOL = new Map(ASSETS.map((a) => [a.symbol, a]));

export function getAsset(symbol: string | undefined): Asset | undefined {
  if (!symbol) return undefined;
  return BY_SYMBOL.get(symbol.toUpperCase());
}

export const POPULAR = ['NVDA', 'AAPL', 'TSLA', 'MSFT', 'AMZN', 'META', 'SPY', 'GOOGL'];

export function searchAssets(query: string): Asset[] {
  const q = query.trim().toLowerCase();
  if (!q) return ASSETS;
  return ASSETS.map((a) => {
    const sym = a.symbol.toLowerCase();
    const name = a.name.toLowerCase();
    let score = -1;
    if (sym === q) score = 100;
    else if (sym.startsWith(q)) score = 80;
    else if (name.startsWith(q)) score = 70;
    else if (name.split(/\s+/).some((w) => w.startsWith(q))) score = 60;
    else if (sym.includes(q)) score = 40;
    else if (name.includes(q)) score = 30;
    else if (a.category.toLowerCase().includes(q)) score = 10;
    return { a, score };
  })
    .filter((x) => x.score >= 0)
    .sort((x, y) => y.score - x.score || x.a.symbol.localeCompare(y.a.symbol))
    .map((x) => x.a);
}
